/*
 * fdir_tree.h — interface of the distilled decision tree (RUNBOOK 4.7).
 * The implementation firmware/src/fdir_tree.c is GENERATED by
 * codegen/emit_tree.py; never edit it by hand.
 *
 * Inputs (per unit, CLAUDE.md order, then the ADR-0019 history from fdir_features.c):
 *   in[0] v_cell   [V per cell]      in[3] soc_ekf  [0..1, onboard EKF]
 *   in[1] c_rate   [C, discharge>0]  in[4] i_sa_pu  [array current / rating]
 *   in[2] t_bat    [degC]            in[5] u_bus_pu [bus voltage / (N_S * 4.2 V)]
 *   in[6] dv60     [V per cell]      in[7] i_sa_sun [sunlit-phase mean of in[4]]
 *   in[8] dsoc600  [SoC change over 10 min]
 * Output: out[0] = S, out[1] = B, out[2] = L, each in 0..3 for every input
 * (CBMC: verify/cbmc/harness_tree.c). The SGO v3 then applies its invariants.
 */
#ifndef FDIR_TREE_H
#define FDIR_TREE_H

#include <stdint.h>

#define FDIR_TREE_INPUTS 9

/* Returns 0 when a leaf was reached, 1 when the tables were structurally inconsistent
 * (then out = SGO safe default S=0, B=1, L=1). */
int  fdir_tree_eval(const float in[FDIR_TREE_INPUTS], uint8_t out[3]);

/* RAM-table mode (FDIR_TREE_IN_RAM): copy tables from flash and record their CRC;
 * scrub returns 1 if the RAM tables were corrupted and have been restored. No-ops otherwise. */
void fdir_tree_init(void);
int  fdir_tree_scrub(void);

/* CRC-32 used by the scrub; provided by the platform in RAM-table mode (hardware CRC on the DUT). */
uint32_t fdir_tree_crc32(const void *data, uint32_t len);

#endif /* FDIR_TREE_H */
